    displayName: string;
    /**
     * The router/entry-point skill a manifest declared, by frontmatter name.
     */
    entryPoint?: string | null;
    /**
     * Optional named groups, e.g. `core` / `on-demand`.
     */
    groups?: {
        [key: string]: unknown;
    };
    id: string;
    installedAt?: string | null;
    installer?: string | null;
